#include <stdio.h>
typedef struct { int value; int offset; } Sample;
static int corrected(Sample s) { return s.value + s.offset; }
int main(void) {
    Sample s;
    if (scanf("%d%d", &s.value, &s.offset) != 2) return 1;
    printf("%d\n", corrected(s));
    return 0;
}
